create policy "site-assets public read" on storage.objects for select using (bucket_id = 'site-assets');
create policy "site-assets owner upload" on storage.objects for insert to authenticated with check (bucket_id = 'site-assets' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "site-assets owner delete" on storage.objects for delete to authenticated using (bucket_id = 'site-assets' and (storage.foldername(name))[1] = auth.uid()::text);